<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
final class V6Schema19LifecycleProvenanceTest extends TestCase{
 public function testSchemaAddsDurableProvenanceAndExplicitClosureState():void{$s=file_get_contents(__DIR__.'/../../includes/Database/V6OperationalSchema.php');self::assertStringContainsString('VERSION=20',$s);self::assertStringContainsString('pod_authorization_bindings',$s);self::assertStringContainsString('external_execution_state varchar(32)',$s);$bootstrap=file_get_contents(__DIR__.'/../../digiforge.php');self::assertStringContainsString("DIGIFORGE_DB_VERSION = '20'",$bootstrap);self::assertStringContainsString("V6_LIFECYCLE_STATE_BACKFILL_FAILED",$s);self::assertStringContainsString("CONFIRMED_SUCCESS",$s);self::assertStringContainsString("CONFIRMED_FAILURE",$s);}
 public function testPermitConsumptionPersistsBindingAndClosureChecksIt():void{$c=file_get_contents(__DIR__.'/../../includes/POD/ProductionExecutionPermitConsumer.php');$atomic=file_get_contents(__DIR__.'/../../includes/POD/ProductionExecutionConsumptionRepository.php');$r=file_get_contents(__DIR__.'/../../includes/POD/ProductionLifecycleClosureRepository.php');self::assertStringContainsString('ProductionExecutionConsumptionRepository::consume',$c);self::assertStringContainsString('pod_authorization_bindings',$atomic);self::assertStringContainsString('production_permit_package_binding_conflict',$atomic);self::assertStringContainsString('production_closure_provenance_conflict',$r);self::assertStringContainsString("'external_execution_state'=>\$executionState",$r);$atomic=file_get_contents(__DIR__.'/../../includes/POD/ProductionExecutionConsumptionRepository.php');self::assertStringContainsString('production_permit_transaction_unavailable',$atomic);self::assertStringContainsString('production_permit_transaction_engine',$atomic);self::assertStringContainsString('information_schema.TABLES',$atomic);$history=file_get_contents(__DIR__.'/../../includes/POD/ProductionLifecycleHistoryReadModel.php');self::assertStringContainsString('production_history_closure_provenance_conflict',$history);$attention=file_get_contents(__DIR__.'/../../includes/Portal/AttentionReadModel.php');self::assertStringContainsString('production_legacy_unbound',$attention);self::assertStringContainsString('production_provenance_integrity',$attention);$drill=file_get_contents(__DIR__.'/../../includes/POD/ProductionProvenanceIntegrityReadModel.php');self::assertStringContainsString('BINDING_PACKAGE_MISMATCH',$drill);self::assertStringContainsString('CLOSURE_PACKAGE_MISMATCH',$drill);self::assertStringContainsString('LEGACY_UNBOUND',$drill);self::assertStringContainsString("'retry_permitted'=>false",$drill);self::assertStringContainsString('correlation_hash',$drill);self::assertStringContainsString('pod_execution_outcomes',$drill);self::assertStringContainsString('pod_lifecycle_closures',$drill);$ack=file_get_contents(__DIR__.'/../../includes/POD/ProductionProvenanceIntegrityAcknowledgementRepository.php');self::assertStringContainsString('ACKNOWLEDGE_INTEGRITY_ANOMALY',$ack);self::assertStringContainsString("'retry_permitted']=false",$ack);self::assertStringContainsString("'external_execution_authorized']=false",$ack);}
}
